import type AutocompleteElement from '@github/auto-complete-element'
import {controller, target, targets} from '@github/catalyst'
import {TemplateInstance} from '@github/template-parts'
import {announceFromElement} from '@github-ui/aria-live'
import {on} from 'delegated-events'
import {validate} from '../behaviors/html-validation'

const NODE_ID_ATTRIBUTE = 'data-node-id'

type Reviewer = {
  displayName: string
  nodeId: string
  avatarUrl: string
}

@controller
class ProtectionRulesElement extends HTMLElement {
  @target declare form: HTMLFormElement
  @target declare autoComplete: AutocompleteElement
  @target declare autoCompleteInput: HTMLInputElement
  @target declare toggle: HTMLInputElement
  @target declare reviewerTemplate: HTMLTemplateElement
  @target declare reviewerList: HTMLUListElement
  @targets declare reviewers: HTMLLIElement[]
  @target declare count: HTMLElement
  @target declare reviewerVerbiage: HTMLElement

  @target declare waitGroup: HTMLElement
  @target declare waitTime: HTMLInputElement
  @target declare waitNote: HTMLElement

  private enabled = false

  connectedCallback() {
    this.update()
  }

  // eslint-disable-next-line @typescript-eslint/no-shadow
  selectSuggestion({target}: {target: HTMLElement}) {
    const value = target.getAttribute('data-node-id')!
    const name = target.getAttribute('data-name')!
    const avatarUrl = target.getAttribute('data-avatar-url')!

    this.addReviewer({
      displayName: name,
      nodeId: value,
      avatarUrl,
    })
  }

  approverToggled() {
    // Whenever the gate is toggled, ensure we update the forms validation status
    this.update()
  }

  addReviewer(reviewer: Reviewer) {
    // Clear the auto-complete input
    this.autoComplete.value = ''

    // Check if it already exists
    if (this.reviewers.some(r => r.getAttribute(NODE_ID_ATTRIBUTE) === reviewer.nodeId)) {
      // Reviewer is already in list
      return
    }

    // Add new reviewer
    const rt = new TemplateInstance(this.reviewerTemplate, {
      name: reviewer.displayName,
      nodeId: reviewer.nodeId,
      avatarUrl: reviewer.avatarUrl,
    })

    this.reviewerList.appendChild(rt)
    this.update()
  }

  removeReviewer(e: Event) {
    const reviewerNodeId = (e.target as HTMLElement).closest('.js-reviewer')?.getAttribute(NODE_ID_ATTRIBUTE)
    if (reviewerNodeId) {
      this.reviewerList.querySelector(`[${NODE_ID_ATTRIBUTE}='${reviewerNodeId}']`)?.remove()
      this.update()
    }
  }

  private get minValidationMessage() {
    return this.getAttribute('min-reviewers-validation-message')
  }

  private get maxReviewers(): number {
    return parseInt(this.getAttribute('max-reviewers') || '6', 10)
  }

  private get invisibleViewersCount(): number {
    return parseInt(this.getAttribute('invisible-viewers-count') || '0', 10)
  }

  validateWaitTime() {
    if (!this.waitTime.validity.valid) {
      this.waitGroup.classList.add('errored')
      announceFromElement(this.waitNote)
    } else {
      this.waitGroup.classList.remove('errored')
    }
  }

  private update() {
    // Update visible reviewer count and verbiage
    const currentCount = this.maxReviewers - this.reviewers.length - this.invisibleViewersCount
    this.count.textContent = `${currentCount}`
    this.reviewerVerbiage.textContent = `${currentCount === 1 ? 'reviewer' : 'reviewers'}`

    // Validate
    if (this.toggle.checked) {
      this.autoCompleteInput.disabled = this.reviewers.length + this.invisibleViewersCount >= this.maxReviewers
      this.toggle.setCustomValidity(
        (this.reviewers.length === 0 && this.invisibleViewersCount === 0 && this.minValidationMessage) || '',
      )
      validate(this.form)
    } else {
      // Do not prevent form submission
      this.toggle.setCustomValidity('')
    }
  }
}

on('click', '.js-show-more-branches', function (event) {
  const button = event.target as HTMLElement
  const container = button.closest<HTMLElement>('.js-hidden-branches-container')!
  const hiddenEnvironments = container.querySelector<HTMLElement>('.js-hidden-branches')
  const shownEnvironments = container.querySelector<HTMLElement>('.js-shown-branches')

  if (shownEnvironments) {
    shownEnvironments.hidden = true
  }

  if (hiddenEnvironments) {
    hiddenEnvironments.hidden = false
  }
})
